commands.command:
ROOT_PW=$(cat /tmp/root_pw.txt); APP_PW=$(cat /tmp/app_pw.txt); sudo mysql <<SQL
ALTER USER 'root'@'localhost' IDENTIFIED BY [REDACTED]
CREATE DATABASE IF NOT EXISTS appdb;
CREATE USER IF NOT EXISTS 'appuser'@'%' IDENTIFIED BY [REDACTED]
GRANT ALL PRIVILEGES ON appdb.* TO 'appuser'@'%';
FLUSH PRIVILEGES;
SQL
echo "exit:$?"
